import os, base64
project = "/mnt/c/Users/DELL/Preeti-portfolio"
files = {}
files["src/components/Hero.jsx"] = ""
files["src/components/Hero.css"] = ""
files["src/components/Certifications.jsx"] = ""
files["src/components/Certifications.css"] = ""
files["src/components/Experience.jsx"] = ""

for rel_path, b64 in files.items():
    full_path = os.path.join(project, rel_path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    content = base64.b64decode(b64).decode('utf-8')
    with open(full_path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f'  written: {rel_path}')
print('All done! Run: npm run dev')